steps.script:
GameState.state["factions"]["2"].merge({"detachment": "Runt Swarm"}, true)
StratagemManager.load_faction_stratagems_for_player(2)
var i := 0
for m in GameState.state.units["U_CUSTODIAN_GUARD_C"].models:
	m["position"] = {"x": 1400.0 + i * 72.0, "y": 1480.0}
	i += 1
GameState.state.units["U_RUNTHERD_A"].models[0]["position"] = {"x": 1720.0, "y": 2120.0}
tree.current_scene._recreate_unit_visuals()
return StratagemManager.get_stratagem("faction_ork_runt_swarm_scarper").get("implemented", false)

var p = PhaseManager.get_current_phase_instance()
var roll := -1
for d in p.dice_log:
	if str(d.get("type", "")) == "SCARPER!":
		roll = int(d.get("roll", -1))
var cap := float(p.active_moves.get("U_GRETCHIN_C", {}).get("move_cap_inches", -1.0))
if roll < 1 or roll > 6:
	return "no D6 in the dice log"
if absf(cap - roll) > 0.01:
	return "cap %s vs roll %d" % [str(cap), roll]
return "ok"

var l = tree.current_scene.status_label
var f = l.get_theme_font("font")
var fs = l.get_theme_font_size("font_size")
return f.get_string_size(l.text, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x <= l.size.x + 1.0
